limit = 10
events = [("D", 5), ("W", 12), ("W", 4), ("F", 0), ("D", 20)]
balance = lowest = 0
for index, (kind, amount) in enumerate(events, start=1):
    if kind == "D":
        balance += amount
    elif kind == "W":
        candidate = balance - amount
        if candidate < -limit:
            print("REJECT", index)
        else:
            balance = candidate
    elif kind == "F":
        if balance < 0:
            balance -= 1
    else:
        raise ValueError("unknown event")
    lowest = min(lowest, balance)
print("BALANCE", balance)
print("MIN", lowest)
